lemma extH_eq_shift {A : Matrix n n ℂ} (hH : A.IsHermitian) {s : ℝ}
    (hs : 0 ≤ s) (hpsd : (A + s • 1).PosSemidef) :
    extH f A = ext f (A + s • 1) - s

lemma extH_finsetSum {ι : Type*} {s : Finset ι} {g : ι → Matrix n n ℂ}
    (hg : ∀ k ∈ s, (g k).IsHermitian) :
    extH f (∑ k ∈ s, g k) = ∑ k ∈ s, extH f (g k)

lemma isHermitian_finsetSum {ι : Type*} {s : Finset ι}
    {g : ι → Matrix n n ℂ} (hg : ∀ k ∈ s, (g k).IsHermitian) :
    (∑ k ∈ s, g k).IsHermitian

lemma scale_indep {A : Matrix n n ℂ} (_hA : A.PosSemidef) {c d : ℝ}
    (hc : 0 < c) (hd : 0 < d) (hdc : d ≤ c) (hde : IsEffect (d⁻¹ • A)) :
    c * f (c⁻¹ • A) = d * f (d⁻¹ • A)

theorem deriv_of_eq_affine_log {f : ℝ → ℝ} {a b : ℝ}
    (h : ∀ r, 0 < r → f r = a + b * Real.log r) {r : ℝ} (hr : 0 < r) :
    deriv f r = b * r⁻¹

theorem deriv_of_eq_affine_radial {n : ℕ} {f : ℝ → ℝ} {a b : ℝ}
    (h : ∀ r, 0 < r → f r = a + b * r ^ (2 - (n : ℝ))) {r : ℝ} (hr : 0 < r) :
    deriv f r = b * ((2 - (n : ℝ)) * r ^ (1 - (n : ℝ)))

theorem hasDerivAt_rpow_mul {n : ℝ} {f' f'' : ℝ → ℝ} {r : ℝ}
    (hf' : HasDerivAt f' (f'' r) r) (hr : 0 < r) :
    HasDerivAt (fun r => r ^ (n - 1) * f' r) (r ^ (n - 1) * (f'' r + (n - 1) / r * f' r)) r

theorem radial_ode_of_eq {n : ℕ} {f : ℝ → ℝ} {a b : ℝ}
    (h : ∀ r, 0 < r → f r = a + b * r ^ (2 - (n : ℝ))) {r : ℝ} (hr : 0 < r) :
    deriv (deriv f) r + ((n : ℝ) - 1) / r * deriv f r = 0
